 function freshProposal(){return proposalFreshnessV1()==='FRESH';}
 // RUN75: the displayed native plan/offer deadline is authoritative for this
// projection's actionability. Expiry detection is latched per displayed plan:
// once the shown deadline passed (real timer or any later update pass), the
// stale cached start/consent actionability is removed and the honest reason
