function notePlanExpiry(p:WorkspaceAgentPlanV1){const o=p.inferenceConsentOffer,nowMs=Date.now(),parts:string[]=[];let offerExpired=false;if(o&&o.expiresAtMs<=nowMs){offerExpired=true;parts.push('Das angezeigte gebundene Angebot ist abgelaufen (Ablauf '+new Date(o.expiresAtMs).toISOString()+', Browseruhr)');}if(p.expiresAtMs<=nowMs)parts.push('Der angezeigte native Plan ist abgelaufen (Ablauf '+new Date(p.expiresAtMs).toISOString()+', Browseruhr)');if(!parts.length)return;root.dataset.planExpiredReason=parts.length===2?'OFFER_AND_PLAN_EXPIRED':offerExpired?'OFFER_EXPIRED':'PLAN_EXPIRED';planExpiryNote=parts.join(' · ')+'. Dieser angezeigte Plan kann nicht mehr starten und verlängert sich nicht; abgelaufene Browseruhr entfernt nur die Handlungsbarkeit und erteilt keine neue Freigabe. Der Auftragstext oben bleibt unverändert und wurde nicht gesendet. Nur ein erneuter ausdrücklicher nativer Plan aus aktuellem Kontext und Auswahl — mit frischem, nicht angehaktem Angebot — startet wieder.';planExpiry.textContent=planExpiryNote;planExpiry.hidden=false;if(root.dataset.state==='PLANNED_NOT_DISPATCHED')state('PLANNED_NOT_DISPATCHED','Angezeigter Plan abgelaufen — kein automatischer Neuversuch, kein Dispatch und kein Retry; der ungesendete Text bleibt erhalten, nur erneut ausdrücklich planen.');}
 function update(){const held=busy||reading;editAction.disabled=held||!options.editor?.frame();selectionAction.disabled=held||!c;info.disabled=held||!c?.primaryObject||!options.openInfo;suggestEdit.disabled=editAction.disabled;suggestSelection.disabled=selectionAction.disabled;suggestInfo.disabled=info.disabled;const offer=plan?.inferenceConsentOffer,nowMs=Date.now(),inertPlan=plan!==null&&!dispatching&&!attempted.has(plan.planHandle);if(inertPlan&&plan&&planExpiryNote===null&&(plan.expiresAtMs<=nowMs||offer&&offer.expiresAtMs<=nowMs))notePlanExpiry(plan);const expiredShown=plan!==null&&planExpiryNote!==null&&inertPlan;if(expiredShown&&offer)transferConsent.checked=false;planExpiry.hidden=!expiredShown;if(!expiredShown)root.removeAttribute('data-plan-expired-reason');makePlan.disabled=held||!usable();start.disabled=held||!usable()||!plan||attempted.has(plan.planHandle)||expiredShown||plan.expiresAtMs<=nowMs||Boolean(offer&&(offer.expiresAtMs<=nowMs||!transferConsent.checked));start.textContent=offer?'Genau diesen gebundenen Lauf einmalig starten':'Genau diesen synthetischen Lauf starten';transferConsent.disabled=held||!offer||offer.expiresAtMs<=nowMs||expiredShown;consentLabel.hidden=!offer||expiredShown;read.disabled=reading||(busy&&!dispatching)||!runId||!c||c.moduleId!=='pan.erv'||!c.primaryObject;review.disabled=held||!freshProposal();input.disabled=held;root.dataset.run=runId??'none';root.dataset.dispatchAvailable=String(!start.disabled);root.dataset.dispatchInFlight=String(dispatching);connectionAction.disabled=held;renderConnectionGuidanceV1();renderTaskOperationsV1();renderProposalFreshnessV1();}
 // RUN88 PUI-07-AC02: render the missing-operation explanation strictly from
 // the CURRENT validated plan/read projection. `result` is set only by a
 // validated native read (resultOf) and `plan` only by a validated plan, both
